import timeit

def measure(operation, repeats=2, number=3):
    if repeats < 1 or number < 1:
        raise ValueError("positive repetition counts required")
    timer = timeit.Timer(operation)
    return timer.repeat(repeat=repeats, number=number)

def counted_measure():
    calls = []
    def operation():
        calls.append(1)
    samples = measure(operation, repeats=2, number=3)
    return len(samples), len(calls), all(value >= 0 for value in samples)

def rejects_count(repeats, number):
    try:
        measure(lambda: 1, repeats=repeats, number=number)
    except ValueError:
        return True
    return False

import cProfile
import pstats

def square(value):
    return value * value

def workload(count):
    total = 0
    for value in range(count):
        total += square(value)
    return total

def profile_work(count):
    profiler = cProfile.Profile()
    result = profiler.runcall(workload, count)
    stats = pstats.Stats(profiler)
    calls = 0
    for key, entry in stats.stats.items():
        if key[2] == "square":
            calls += entry[1]
    return result, calls
